const express = require('express');
const Task = require('../models/task');
const authenticateToken = require('../middleware/auth');

const router = express.Router();

router.use(authenticateToken);

router.post('/', (req, res) => {
  const { title, description } = req.body || {};
  const cleanTitle = (title || '').trim();
  if (!cleanTitle) return res.status(400).json({ error: 'Title is required' });
  const task = Task.create({ user_id: req.user.id, title: cleanTitle, description: description || '' });
  return res.status(201).json({ message: 'Task created successfully', task });
});

router.get('/', (req, res) => {
  const tasks = Task.findByUser(req.user.id);
  return res.status(200).json({ tasks });
});

router.get('/:id', (req, res) => {
  const taskId = parseInt(req.params.id, 10);
  if (isNaN(taskId)) return res.status(404).json({ error: 'Task not found' });
  const task = Task.findById(taskId, req.user.id);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  return res.status(200).json({ task });
});

const updateHandler = (req, res) => {
  const taskId = parseInt(req.params.id, 10);
  if (isNaN(taskId)) return res.status(404).json({ error: 'Task not found' });
  const existing = Task.findById(taskId, req.user.id);
  if (!existing) return res.status(404).json({ error: 'Task not found' });

  const updates = {};
  if ('title' in req.body) {
    const cleanTitle = String(req.body.title || '').trim();
    if (!cleanTitle) return res.status(400).json({ error: 'Title cannot be empty' });
    updates.title = cleanTitle;
  }
  if ('description' in req.body) updates.description = req.body.description;
  if ('is_completed' in req.body) updates.is_completed = Boolean(req.body.is_completed);

  const task = Task.update(taskId, req.user.id, updates);
  return res.status(200).json({ message: 'Task updated successfully', task });
};

router.put('/:id', updateHandler);
router.patch('/:id', updateHandler);

module.exports = router;

